export function renderExpenses(expenses: Expenses) {
  const list = document.getElementById('expensesList') as HTMLDivElement;
  list.innerHTML = '';
  const total = expenses.reduce((s, e) => s + e.amount, 0);
  document.getElementById('totalAmount')!.textContent = total.toFixed(2);
  expenses.forEach((e) => {
    const row = document.createElement('div');
    row.className = 'card';
    row.innerHTML = `
