import { gameLoop } from './game-loop.js';

let snake = [{ x: 10, y: 10 }], direction = { x: 1, y: 0 }, food = { x: 15, y: 15 }, score = 0, canvas;

function handleInput(e) {
  switch (e.key) {
    case 'ArrowUp': direction = { x: 0, y: -1 }; break;
    case 'ArrowDown': direction = { x: 0, y: 1 }; break;
    case 'ArrowLeft': direction = { x: -1, y: 0 }; break;
    case 'ArrowRight': direction = { x: 1, y: 0 }; break;
  }
}

function moveSnake() {
  snake.push({ x: snake[0].x + direction.x, y: snake[0].y + direction.y });
  if (snake[0].x < 0 || snake[0].x >= 20 || snake[0].y < 0 || snake[0].y >= 20) {
    snake[0] = { x: 10, y: 10 };
    snake.splice(1);
  }
  if (snake[0].x === food.x && snake[0].y === food.y) {
    score += 1;
    food = { x: Math.floor(Math.random() * 20), y: Math.floor(Math.random() * 20) };
    snake.push({ x: snake[snake.length - 1].x + direction.x, y: snake[snake.length - 1].y + direction.y });
  } else {
    snake.splice(0, 1);
  }
}

function draw() {
  gameLoop(snake, food, canvas);
}

function checkCollisions() {
  for (let i = 1; i < snake.length; i++) {
    if (snake[0].x === snake[i].x && snake[0].y === snake[i].y) {
      return true;
    }
  }
  return false;
}

export function startGame(canvasEl) {
  canvas = canvasEl;
  canvas.width = 400;
  canvas.height = 400;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = 'var(--bg)';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  const scoreDisplay = document.getElementById('score');
  const gameScore = document.getElementById('game-score');
  const gameOver = document.getElementById('game-over');
  const gameCanvas = document.getElementById('game-canvas');
  gameCanvas.addEventListener('keydown', handleInput);
  let intervalId = null;
  function gameTick() {
    moveSnake();
    if (checkCollisions()) {
      clearInterval(intervalId);
      gameOver.style.display = 'block';
      gameScore.textContent = 'Score: ' + score;
    } else {
      draw();
    }
  }
  intervalId = setInterval(gameTick, 100);
}

