function generateMaze() {
  open = Array.from({ length: SIZE }, () => Array(SIZE).fill(false));
  const stack = [[1, 1]];
  open[1][1] = true;
  const dirs = [[0, -2], [0, 2], [-2, 0], [2, 0]];
  while (stack.length) {
    const [cx, cz] = stack[stack.length - 1];
    const cands = [];
    for (const [dx, dz] of dirs) {
      const nx = cx + dx, nz = cz + dz;
      if (nx > 0 && nx < SIZE - 1 && nz > 0 && nz < SIZE - 1 && !open[nx][nz]) cands.push([nx, nz]);
    }
    if (cands.length === 0) { stack.pop(); continue; }
    const [nx, nz] = cands[Math.floor(Math.random() * cands.length)];
    open[(cx + nx) / 2][(cz + nz) / 2] = true;
    open[nx][nz] = true;
    stack.push([nx, nz]);
  }
}
function tryMove(nx, nz) {
  const margin = 0.32;
  const corners = [[nx + margin, nz + margin], [nx - margin, nz + margin],
                   [nx + margin, nz - margin], [nx - margin, nz - margin]];
  for (const [cx, cz] of corners) {
    if (cx < 0 || cz < 0 || cx >= SIZE || cz >= SIZE) return false;
    if (!open[Math.floor(cx)][Math.floor(cz)]) return false;
  }
  player.x = nx; player.z = nz;
  return true;
}
