const planetGroups = [];
PLANETS.forEach((p) => {
  const group = new THREE.Group();
  const body = new THREE.Mesh(
    new THREE.SphereGeometry(p.radius, 40, 40),
    new THREE.MeshStandardMaterial({ color: p.color, metalness: 0.25, roughness: 0.7 })
  );
  body.castShadow = true;
  group.add(body);
  if (p.ring) {
    const ring = new THREE.Mesh(
      new THREE.RingGeometry(p.radius * 1.4, p.radius * 2.2, 64),
      new THREE.MeshStandardMaterial({ color: 0xcbb07a, metalness: 0.4, roughness: 0.6, side: THREE.DoubleSide })
    );
    ring.rotation.x = Math.PI / 2.4;
    group.add(ring);
  }
  group.userData = { angle: Math.random() * Math.PI * 2, speed: p.speed, dist: p.dist };
  group.position.set(Math.cos(group.userData.angle) * p.dist, 0, Math.sin(group.userData.angle) * p.dist);
  scene.add(group);
  planetGroups.push(group);
});
// per frame (dt-based):
for (const g of planetGroups) {
  g.userData.angle += g.userData.speed * dt;
  g.position.set(Math.cos(g.userData.angle) * g.userData.dist, 0, Math.sin(g.userData.angle) * g.userData.dist);
}

function explode(x, y, z, color) {
  const n = 160;
  const pos = new Float32Array(n * 3);
  const vel = new Float32Array(n * 3);
  const col = new Float32Array(n * 3);
  const c = new THREE.Color(color);
  for (let i = 0; i < n; i++) {
    pos[i * 3] = x; pos[i * 3 + 1] = y; pos[i * 3 + 2] = z;
    const th = Math.random() * Math.PI * 2;
    const ph = Math.acos(2 * Math.random() - 1);
    const sp = 1.5 + Math.random() * 3.5;
    vel[i * 3] = Math.sin(ph) * Math.cos(th) * sp;
    vel[i * 3 + 1] = Math.cos(ph) * sp;
    vel[i * 3 + 2] = Math.sin(ph) * Math.sin(th) * sp;
    col[i * 3] = c.r; col[i * 3 + 1] = c.g; col[i * 3 + 2] = c.b;
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  geo.setAttribute('color', new THREE.BufferAttribute(col, 3));
  const points = new THREE.Points(geo, new THREE.PointsMaterial({
    size: 0.22, vertexColors: true, transparent: true, opacity: 1,
    blending: THREE.AdditiveBlending, depthWrite: false,
  }));
  scene.add(points);
  bursts.push({ points, pos, vel, life: 0, maxLife: 1.6 + Math.random() * 0.6 });
}
